<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';
import type {PoolContext,PoolFilters,PoolMemory,PoolPage,PoolPacket,PoolReceipt} from '../types/negative-pool';
import type {AlgorithmSummary,Paged} from '../types/model-browse';
import {negativePoolApi,frozenPoolPacket,checkPoolReceipt} from '../api/negative-pool';
import {modelBrowseApi} from '../api/model-browse';
import {useReadScope} from '../composables/useReadScope';
import PageHeader from '../components/PageHeader.vue';
import MaterialPreview from '../components/MaterialPreview.vue';
const props=defineProps<{context:PoolContext}>(),reads=useReadScope(props.context),api=negativePoolApi(props.context),catalog=modelBrowseApi(props.context),saved=props.context.memory.negativePool;
const pending=ref<PoolPacket|null>(null),invalidPending=ref('');try{pending.value=frozenPoolPacket(props.context.poolPending.value)}catch(error){invalidPending.value=error instanceof Error?error.message:'待确认操作无法读取'}
const algorithm=ref(pending.value?.project_id===props.context.projectId?pending.value.algorithm_id:saved?.algorithmId||props.context.memory.selection?.algorithmId||''),filters=reactive<PoolFilters>({query:'',category_id:'',label:'',joined_days:'',review_status:'',target_label:'',...saved?.filters}),number=ref(saved?.algorithmId===algorithm.value?saved.page:1),selected=ref<string[]>(saved?.algorithmId===algorithm.value?saved.selected:[]),page=ref<PoolPage|null>(null),algorithms=ref<Paged<AlgorithmSummary>|null>(null),algorithmPage=ref(1),algorithmQuery=ref(''),confirm=ref<PoolPacket|null>(null),receipt=ref<PoolReceipt|null>(null),note=ref(''),knownRejected=ref(false);
const blocked=computed(()=>!!pending.value||!!invalidPending.value||!!reads.busy.write),candidateIds=ref([...new Set(props.context.memory.materials?.selectedItems||[])]),sameScope=computed(()=>pending.value?.project_id===props.context.projectId&&pending.value?.algorithm_id===algorithm.value);
const reviewLabels:Record<string,string>={unannotated:'未标注',annotated:'已标注',confirmed_empty:'已确认无目标',stale:'需重新审核'};
function remember(){props.context.memory.negativePool={algorithmId:algorithm.value,filters:{...filters},page:number.value,selected:[...selected.value]} as PoolMemory}
function load(){remember();if(!algorithm.value)return;return reads.run('pool',signal=>api.list(algorithm.value,{...filters},number.value,signal),value=>{page.value=value})}
function search(){number.value=1;void load()}
function changeAlgorithm(){reads.cancel('pool');reads.cancel('write');page.value=null;selected.value=[];number.value=1;confirm.value=null;receipt.value=null;void load()}
function loadAlgorithms(){void reads.run('algorithms',signal=>catalog.algorithms({page:algorithmPage.value,query:algorithmQuery.value},signal),value=>{algorithms.value=value})}
function choose(id:string,value:boolean){if(value&&!selected.value.includes(id)){if(selected.value.length===200){note.value='最多选择 200 张';return}selected.value.push(id)}if(!value)selected.value=selected.value.filter(x=>x!==id);remember()}
function prepare(action:'add'|'remove'){if(blocked.value||!algorithm.value||!page.value||reads.busy.pool||reads.errors.pool)return;const ids=action==='add'?candidateIds.value:selected.value;if(!ids.length)return;if(ids.length>200){note.value='一次成员操作最多 200 张，请返回素材库缩小明确选择。';return}confirm.value={project_id:props.context.projectId,algorithm_id:algorithm.value,image_ids:[...ids],action,expected_revision:page.value.negative_pool_revision,operation_id:props.context.createOperationId(),report_counts:true};note.value=''}
function finish(packet:PoolPacket,result:PoolReceipt,newPage:PoolPage){page.value=newPage;receipt.value=result;selected.value=[];if(packet.action==='add'&&props.context.memory.materials){props.context.memory.materials.selectedItems=props.context.memory.materials.selectedItems.filter(id=>!packet.image_ids.includes(id));candidateIds.value=[...props.context.memory.materials.selectedItems]}props.context.poolPending.save(null);pending.value=null;confirm.value=null;remember();note.value='已收到原负样本池回执并刷新当前范围'}
async function execute(mode:'submit'|'receipt'|'replay'){
 const packet=mode==='submit'?confirm.value:pending.value;if(!packet||packet.project_id!==props.context.projectId||packet.algorithm_id!==algorithm.value)return;
 if(mode==='submit'){try{props.context.poolPending.save(packet);pending.value=frozenPoolPacket(packet);confirm.value=null}catch(error){note.value='无法保存待确认请求，未提交。'+(error instanceof Error?error.message:'');return}}
 const frozen=frozenPoolPacket(packet)!;const currentFilters={...filters},currentPage=number.value;
 void reads.run('write',async signal=>{let result:PoolReceipt;try{result=mode==='receipt'?await api.receipt(frozen,signal):checkPoolReceipt(await props.context.poolWrite(frozen),frozen)}catch(error){if(mode!=='receipt'&&((error as {httpStatus?:number;status?:number}).httpStatus??(error as {status?:number}).status)===409)knownRejected.value=true;throw error}const refreshed=await api.list(frozen.algorithm_id,currentFilters,currentPage,signal);if(BigInt(refreshed.negative_pool_revision)<BigInt(result.negative_pool_revision))throw new Error('刷新修订早于操作回执，请重新核验');return {result,refreshed}},({result,refreshed})=>finish(frozen,result,refreshed));
}
function discardRejected(){const packet=pending.value;if(!packet||!knownRejected.value||!sameScope.value)return;void reads.run('write',signal=>api.list(packet.algorithm_id,{...filters},number.value,signal),value=>{page.value=value;props.context.poolPending.save(null);pending.value=null;knownRejected.value=false;selected.value=[];remember();note.value='原意图已被拒绝，已刷新。请重新选择并确认新操作。'})}
function trainingUsage(value:unknown){if(typeof value==='string')return value;if(value&&typeof value==='object'){const v=value as {state?:string;current_algorithm_trained?:boolean;other_algorithm_trained?:boolean};return `${v.state||'未知'} · 当前算法已训练：${v.current_algorithm_trained===undefined?'未知':v.current_algorithm_trained?'是':'否'} · 其他算法已训练：${v.other_algorithm_trained===undefined?'未知':v.other_algorithm_trained?'是':'否'}`}return '未知'}
function filename(value:string){return value.split(/[\\/]/).pop()||'图片'}
function back(){remember();props.context.openMaterials?.()}
onMounted(()=>{loadAlgorithms();void load()});
</script>
<template><section class="catalog-preview negative-pool" aria-label="算法负样本池"><PageHeader title="负样本池" eyebrow="数据管理 / 算法级负样本池" description="池成员是管理关系。标注状态、审核范围和训练资格由原服务判断。" badge="算法级" @back="context.legacyPool"/><div class="preview-actions"><el-button v-if="context.openMaterials" @click="back">返回素材库</el-button><el-button @click="remember();context.legacyPool()">原审核与分类管理</el-button></div>
<el-alert v-if="invalidPending" :title="invalidPending" type="error" :closable="false"/><section v-if="pending" class="pending-panel"><h3>有一笔操作结果待确认</h3><p>项目 {{ pending.project_id }} · 算法 {{ pending.algorithm_id }} · {{ pending.action==='add'?'加入':'移出' }} {{ pending.image_ids.length }} 张</p><p>操作 {{ pending.operation_id }}。确认回执并刷新成功前保留原请求，禁止新操作。</p><p v-if="!sameScope">请回到该项目及算法恢复操作。</p><div v-else class="preview-actions"><el-button :loading="reads.busy.write" @click="execute('receipt')">查询原回执</el-button><el-button :disabled="reads.busy.write" @click="execute('replay')">使用原请求恢复</el-button></div><div v-if="knownRejected&&sameScope"><p>原意图已被服务端明确拒绝，未创建新操作。</p><el-button :disabled="reads.busy.write" @click="discardRejected">刷新并放弃已拒绝意图</el-button></div></section>
<el-alert v-if="reads.errors.write" :title="reads.errors.write+'；原请求已保留，请查询回执。冲突不能自动建立新请求。'" type="error" :closable="false"/><el-alert v-if="note" :title="note" type="info" :closable="false"/>
<form class="algorithm-picker" @submit.prevent="algorithmPage=1;loadAlgorithms()"><el-input v-model="algorithmQuery" aria-label="搜索算法" placeholder="查找算法名称"/><el-button native-type="submit" :disabled="reads.busy.algorithms">搜索算法</el-button><el-select v-model="algorithm" aria-label="选择算法" placeholder="先选择算法" :disabled="blocked||!!confirm" @change="changeAlgorithm"><el-option v-if="algorithm&&!algorithms?.items.some(a=>a.id===algorithm)" :label="algorithm" :value="algorithm"/><el-option v-for="item in algorithms?.items||[]" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-button :disabled="algorithmPage<=1||reads.busy.algorithms" @click="algorithmPage--;loadAlgorithms()">上页算法</el-button><el-button :disabled="!algorithms||algorithmPage*algorithms.page_size>=algorithms.total||reads.busy.algorithms" @click="algorithmPage++;loadAlgorithms()">下页算法</el-button></form><el-alert v-if="reads.errors.algorithms" :title="reads.errors.algorithms" type="error" :closable="false"/>
<el-empty v-if="!algorithm" description="请选择算法后浏览该算法的负样本池"/><template v-else><form class="pool-filters" :inert="reads.busy.write" @submit.prevent="search"><el-input v-model="filters.query" aria-label="池素材名称" placeholder="搜索名称或素材 ID"/><el-select v-model="filters.review_status" aria-label="审核状态"><el-option label="全部审核状态" value=""/><el-option v-for="(label,value) in reviewLabels" :key="value" :label="label" :value="value"/></el-select><el-button native-type="submit" type="primary" :disabled="reads.busy.pool||reads.busy.write">查询</el-button><el-button :disabled="reads.busy.pool||reads.busy.write" @click="load">刷新</el-button><details><summary>更多筛选条件</summary><div class="extra"><label>类别 ID（只读筛选）<el-input v-model="filters.category_id"/></label><label>标注标签编码<el-input v-model="filters.label"/></label><label>加入时间<el-select v-model="filters.joined_days"><el-option label="全部" value=""/><el-option label="最近 7 天" value="7"/><el-option label="最近 30 天" value="30"/></el-select></label><label>目标标签编码<el-input v-model="filters.target_label" placeholder="多个编码用逗号分隔，需完整继承范围"/></label></div></details></form>
<div class="pool-summary"><span>素材库明确选择 {{ candidateIds.length }} 张 · 池内选择 {{ selected.length }} 张 · 当前筛选 {{ page?.total??'—' }} 张</span><div class="preview-actions"><el-button :disabled="blocked||!page||!candidateIds.length||reads.busy.pool||!!confirm" @click="prepare('add')">加入已选素材</el-button><el-button :disabled="blocked||!page||!selected.length||reads.busy.pool||!!confirm" @click="prepare('remove')">移出池内选择</el-button><el-button @click="selected=[];remember()">清除池内选择</el-button></div></div>
<section v-if="confirm" class="confirm-panel"><h3>确认{{ confirm.action==='add'?'加入':'移出' }}当前算法负样本池</h3><p>算法 {{ confirm.algorithm_id }} · {{ confirm.image_ids.length }} 张明确选择。此操作仅修改池成员关系。</p><el-button type="primary" @click="execute('submit')">确认{{ confirm.action==='add'?'加入':'移出' }}</el-button><el-button @click="confirm=null">取消</el-button></section>
<p v-if="receipt" class="receipt">原回执：{{ receipt.action==='add'?`新增 ${receipt.added} 张，已在池中 ${receipt.already_present} 张`:`移出 ${receipt.removed} 张，原已不在池中 ${receipt.already_absent} 张` }} · 修订 {{ receipt.negative_pool_revision }}</p>
<el-alert v-if="reads.errors.pool" :title="reads.errors.pool" type="error" :closable="false"/><p v-if="reads.errors.pool&&page">下方为上次读取的结果，请刷新后操作。</p><el-skeleton v-if="!page&&reads.busy.pool" :rows="8" animated/><el-empty v-else-if="page&&!page.items.length" description="当前算法与条件下没有池成员"/><div v-if="page" class="pool-grid" :aria-busy="reads.busy.pool"><article v-for="row in page.items" :key="row.id"><MaterialPreview :image="row" :project-id="context.projectId" :boxes="row.annotation_preview"/><div class="pool-copy"><el-checkbox :disabled="reads.busy.write" :model-value="selected.includes(row.id)" :aria-label="`选择池素材 ${filename(row.filename)}`" @change="(value:unknown)=>choose(row.id,!!value)">{{ filename(row.filename) }}</el-checkbox><p>审核：{{ reviewLabels[row.negative_pool.review_status||'']||row.negative_pool.review_status||'未知' }}</p><p>加入：{{ row.negative_pool.joined_at||'未提供' }}</p><p>类别：{{ row.negative_pool.categories?.map(c=>c.name).join('、')||'未分类' }}</p><p>服务端资格：{{ row.negative_pool.algorithm_qualification||row.negative_pool.qualification||'未知' }}</p><p>训练使用：{{ trainingUsage(row.negative_pool.training_usage) }}</p><small>在池中不等于可用于训练；请在原审核入口确认。</small></div></article></div><footer v-if="page" class="preview-pagination"><span>第 {{ page.page }} 页 · 每页 {{ page.page_size }} 张 · 修订 {{ page.negative_pool_revision }}</span><div class="preview-actions"><el-button :disabled="number<=1||reads.busy.pool||reads.busy.write" @click="number--;load()">上一页</el-button><el-button :disabled="number*page.page_size>=page.total||reads.busy.pool||reads.busy.write" @click="number++;load()">下一页</el-button></div></footer></template></section></template>
<style scoped>
.algorithm-picker,.pool-filters{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:20px 0}.algorithm-picker>.el-input,.pool-filters>.el-input{flex:1;min-width:180px}.algorithm-picker>.el-select{min-width:210px}.pool-filters>.el-select{width:190px}.pool-filters details{width:100%;padding:12px;border:1px solid #dce4ef;border-radius:10px}.pool-filters summary{cursor:pointer}.extra{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;padding-top:14px}.extra label{display:grid;gap:7px;color:#475569}.pool-summary{display:flex;flex-wrap:wrap;align-items:center;gap:14px;justify-content:space-between;margin:18px 0}.pending-panel,.confirm-panel{border:1px solid #fbbf24;border-radius:12px;padding:18px;margin:16px 0;background:#fffbeb;overflow-wrap:anywhere}.receipt{padding:12px;color:#166534;background:#f0fdf4;border-radius:8px}.pool-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(215px,1fr));gap:16px}.pool-grid article{border:1px solid #dce4ef;border-radius:12px;overflow:hidden;background:white;min-width:0}.pool-copy{padding:12px;overflow-wrap:anywhere}.pool-copy p{font-size:13px;color:#475569}.pool-copy small{color:#64748b}.pool-copy :deep(.el-checkbox__label){white-space:normal;overflow-wrap:anywhere}.pool-copy .el-checkbox{height:auto;max-width:100%}@media(max-width:760px){.extra{grid-template-columns:repeat(2,minmax(0,1fr))}.pool-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:420px){.extra,.pool-grid{grid-template-columns:1fr}}
</style>
